CREATE TABLE IF NOT EXISTS administrator(id INTEGER PRIMARY KEY CHECK(id=1),username TEXT NOT NULL,salt TEXT NOT NULL,password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username TEXT NOT NULL UNIQUE,salt TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','viewer','coordinator')),lga TEXT NOT NULL DEFAULT '',wards TEXT NOT NULL DEFAULT '[]',active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS pus(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,lga TEXT NOT NULL CHECK(lga IN ('Apa','Agatu')),ward TEXT NOT NULL,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,voters INTEGER CHECK(voters>=0),source TEXT NOT NULL,source_date TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS agents(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,pu_id BIGINT NOT NULL REFERENCES pus(id),name TEXT NOT NULL,phone TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('Primary','Backup')),status TEXT NOT NULL CHECK(status IN ('Pending','Confirmed','Trained')),consent INTEGER NOT NULL CHECK(consent=1),archived_at TEXT);
CREATE TABLE IF NOT EXISTS reports(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,pu_id BIGINT NOT NULL REFERENCES pus(id),category TEXT NOT NULL CHECK(category IN ('Logistics','Incident','Community concern')),detail TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'));
CREATE TABLE IF NOT EXISTS activity_log(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,entity TEXT NOT NULL,record_id BIGINT,summary TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'));
CREATE TABLE IF NOT EXISTS voter_baselines(pu_code TEXT NOT NULL,year INTEGER NOT NULL,registered_voters INTEGER NOT NULL CHECK(registered_voters>=0),source_url TEXT NOT NULL,retrieved_on TEXT NOT NULL,PRIMARY KEY(pu_code,year));
CREATE INDEX IF NOT EXISTS agents_pu_idx ON agents(pu_id);
CREATE INDEX IF NOT EXISTS reports_pu_idx ON reports(pu_id);
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY);
INSERT INTO schema_migrations(version) VALUES(1) ON CONFLICT DO NOTHING;
